class ApiError extends Error { constructor(message: string, public status: number) { super(message); this.name = "ApiError"; } }
async function request<T>(url: string, options: RequestInit = {}): Promise<T> {
  const headers = new Headers(options.headers); if (typeof options.body === "string") headers.set("Content-Type", "application/json");
  const response = await fetch(url, { ...options, headers, credentials: "same-origin" });
  const data = await response.json().catch(() => {throw new ApiError("서버 응답 수신이 완료되지 않았습니다. 저장된 진행 상태를 다시 불러와 주세요.",response.status);}) as Record<string, unknown>;
  if (!response.ok) throw new ApiError(typeof data.error === "string" ? data.error : typeof data.message === "string" ? data.message : `요청을 완료하지 못했습니다. (${response.status})`, response.status);
  return data as T;
}
function shortDate(value?: string) { if (!value) return "—"; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat("ko-KR", { month: "short", day: "numeric" }).format(date); }
function today() { return new Intl.DateTimeFormat("sv-SE", { timeZone: "Asia/Seoul", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date()); }
function textValue(value: Json | undefined): string { if (value === undefined || value === null || value === "") return "미확인"; if (typeof value === "boolean") return value ? "있음" : "없음"; return typeof value === "object" ? JSON.stringify(value) : String(value); }
function label(fact: Fact) { return LABELS[fact.key] ?? fact.key.replaceAll("_", " "); }
function count(value: unknown) { return typeof value === "number" ? value : Array.isArray(value) ? value.length : 0; }
function Badge({ children, tone = "neutral" }: { children: ReactNode; tone?: "neutral" | "green" | "amber" | "red" | "blue" }) { return <span className={`badge badge-${tone}`}>{children}</span>; }
function Empty({ icon: Icon = FolderOpen, title, description, action }: { icon?: LucideIcon; title: string; description: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon"><Icon size={24} strokeWidth={1.4} /></div><h3>{title}</h3><p>{description}</p>{action}</div>; }
function Modal({ title, subtitle, children, onClose, wide = false }: { title: string; subtitle?: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  useEffect(() => { const listener = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); }; window.addEventListener("keydown", listener); return () => window.removeEventListener("keydown", listener); }, [onClose]);
  return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className={`modal ${wide ? "modal-wide" : ""}`} role="dialog" aria-modal="true" aria-label={title}><div className="modal-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" onClick={onClose} aria-label="닫기"><X size={20} /></button></div>{children}</section></div>;
}

