  const fileInput = useRef<HTMLInputElement>(null); const pause = useRef(false); const caseRef = useRef<CaseData | null>(null); const caseLoadSequence = useRef(0); const noticeTimer = useRef<ReturnType<typeof setTimeout> | null>(null); const previewBindingRef=useRef({caseId:"",documentId:"",page:0,jobId:""});
  const notify = useCallback((message: string, type: Notice["type"] = "info") => { setNotice({ message, type }); if (noticeTimer.current) clearTimeout(noticeTimer.current); noticeTimer.current = setTimeout(() => setNotice(null), type === "error" ? 10000 : 6000); }, []);
